            [[- |cffffd100The Defias Brotherhood|r: Gryan Stoutmantle |cff9d9d9d(56.2, 47.4)|r. You're on this chain.]],
            [[- |cffffd100Red Silk Bandanas|r: Scout Riell, top of the tower |cff9d9d9d(56.6, 47.4)|r.]],
            [[|cff7fd35bStormwind, Dwarven District:|r]],
